<?php
session_start(); require_once('check-login.php'); require_once('staff-permission-utils.php'); staff_permission_ensure_table($con); $role=staff_permission_role(); if(!in_array($role,array('assistant_head_academic','assistant_head_administration','headmaster','super_admin'),true)){ http_response_code(403); exit('You cannot review staff permission requests.'); }
if(empty($_SESSION['staff_permission_review_csrf'])){ $_SESSION['staff_permission_review_csrf']=bin2hex(random_bytes(32)); } $message='';
if($_SERVER['REQUEST_METHOD']==='POST' && hash_equals($_SESSION['staff_permission_review_csrf'],isset($_POST['csrf'])?$_POST['csrf']:'')){ $id=(int)$_POST['request_id']; $decision=$_POST['decision']==='approved'?'approved':'declined'; $note=trim(isset($_POST['decision_note'])?$_POST['decision_note']:''); $stmt=mysqli_prepare($con,"UPDATE tblstaffpermissionrequest SET status=?,decision_note=?,decided_by=?,decided_at=NOW() WHERE request_id=? AND approver_role=? AND status='pending'"); $user=$_SESSION['USERID']; mysqli_stmt_bind_param($stmt,'sssis',$decision,$note,$user,$id,$role); mysqli_stmt_execute($stmt); mysqli_stmt_close($stmt); $message='Request decision saved.'; }
$roleEsc=mysqli_real_escape_string($con,$role); $requests=@mysqli_query($con,"SELECT r.*, CONCAT(COALESCE(u.firstname,''),' ',COALESCE(u.othernames,''),' ',COALESCE(u.surname,'')) AS requester_name FROM tblstaffpermissionrequest r LEFT JOIN tblsystemuser u ON u.userid=r.requester_id WHERE r.approver_role='$roleEsc' ORDER BY r.status='pending' DESC,r.created_at DESC");
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Review Staff Permissions</title><style>body{margin:0;background:#f3f6f8;color:#15283b;font:16px Arial}.wrap{max-width:1000px;margin:35px auto;padding:0 20px}.card{background:#fff;padding:22px;border:1px solid #dce5eb;border-radius:10px;margin-bottom:18px}.request{border-top:1px solid #dce5eb;padding:18px 0}.request:first-of-type{border:0}textarea{width:100%;box-sizing:border-box;min-height:65px;padding:9px}.button{padding:10px 14px;border:0;border-radius:6px;color:#fff;font-weight:bold;margin:8px 7px 0 0}.approve{background:#15803d}.decline{background:#b91c1c}.pending{color:#b45309;font-weight:bold}.status{font-weight:bold}</style></head><body><main class="wrap"><div class="card"><h1>Review Staff Permission Requests</h1><?php if($message!==''){ ?><p class="status"><?php echo staff_permission_escape($message); ?></p><?php } ?><?php if($requests){ while($row=mysqli_fetch_assoc($requests)){ ?><article class="request"><h2><?php echo staff_permission_escape(trim($row['requester_name'])!==''?$row['requester_name']:$row['requester_id']); ?></h2><p><b><?php echo staff_permission_escape($row['permission_type']); ?></b> · <?php echo staff_permission_escape($row['start_datetime']); ?> to <?php echo staff_permission_escape($row['end_datetime']); ?> · <span class="<?php echo staff_permission_escape($row['status']); ?>"><?php echo staff_permission_escape(ucfirst($row['status'])); ?></span></p><p><?php echo nl2br(staff_permission_escape($row['reason'])); ?></p><?php if($row['status']==='pending'){ ?><form method="post"><input type="hidden" name="csrf" value="<?php echo staff_permission_escape($_SESSION['staff_permission_review_csrf']); ?>"><input type="hidden" name="request_id" value="<?php echo (int)$row['request_id']; ?>"><textarea name="decision_note" placeholder="Decision note (optional)"></textarea><br><button class="button approve" name="decision" value="approved">Approve</button><button class="button decline" name="decision" value="declined">Decline</button></form><?php } else { ?><p><b>Decision note:</b> <?php echo staff_permission_escape($row['decision_note']); ?></p><?php } ?></article><?php } } ?></div></main></body></html>
